      return Result.success(null);
    }

    try {
      final client = SupabaseClientProvider.client!;

      await client
          .from('bookmarks')
          .delete()
          .eq('user_id', userId)
          .eq('post_id', postId);

      return Result.success(null);
    } catch (e, stack) {
      _logError('removeBookmark', e, stack);
