    }
  }

  /// Loads all bookmarked posts for a user.
  @override
  Future<Result<List<Post>>> loadBookmarks(String userId) async {
    if (!SupabaseClientProvider.isInitialized) {
      return Result.success(<Post>[]);
    }

    try {
      final client = SupabaseClientProvider.client!;

      final response = await client
          .from('bookmarks')
          .select('''
            post_id,
            posts!inner (
              *,
              profiles!posts_user_id_fkey (
                user_id,
                username,
                display_name,
                avatar,
                aura_points
              )
            )
          ''')
          .eq('user_id', userId)
          .order('created_at', ascending: false);

      final posts = response.map((row) {
        final post = row['posts'] as Map<String, dynamic>;
        final profile = post['profiles'] as Map<String, dynamic>?;

        return Post(
          id: post['id'] as String,
          userId: post['user_id'] as String,
          username: profile?['username'] as String? ?? 'user',
          displayName: profile?['display_name'] as String?,
          avatarUrl: profile?['avatar'] as String?,
          content: post['content'] as String? ?? '',
          mediaUrls: post['media_urls'] != null
              ? List<String>.from(post['media_urls'] as List)
              : <String>[],
          likes: post['likes_count'] as int? ?? 0,
          comments: post['comments_count'] as int? ?? 0,
          shares: post['shares_count'] as int? ?? 0,
          createdAt:
              DateTime.tryParse(post['created_at'] as String? ?? '') ??
              DateTime.now(),
          updatedAt: post['updated_at'] != null
              ? DateTime.tryParse(post['updated_at'] as String? ?? '')
              : null,
        );
      }).toList();

      return Result.success(posts);
    } catch (e, stack) {
      _logError('loadBookmarks', e, stack);
      return Result.failure(backendFailure(e, stack));
    }
  }

  // ──────────────────────────────────────────────────────────────
  // Comment Likes
  // ──────────────────────────────────────────────────────────────

  /// Toggles a like on a comment in the `comment_likes` table.
  ///
  /// The `comment_likes` table uses `gen_random_uuid()` for its own
  /// primary key, so no `id` is sent on insert.
  @override
  Future<Result<LikeToggleResult>> toggleCommentLike(
    String commentId,
    String userId,
  ) async {
    if (!SupabaseClientProvider.isInitialized) {
      return Result.failure(const Failure('Supabase not initialized'));
    }

    try {
      final client = SupabaseClientProvider.client!;

      final existingLike = await client
          .from('comment_likes')
          .select()
          .eq('comment_id', commentId)
          .eq('user_id', userId)
          .maybeSingle();

      if (existingLike != null) {
        await client
            .from('comment_likes')
            .delete()
            .eq('comment_id', commentId)
            .eq('user_id', userId);

        return Result.success(const LikeToggleResult(isLiked: false, likes: 0));
      }

      await client.from('comment_likes').insert({
        'comment_id': commentId,
        'user_id': userId,
      });

      return Result.success(const LikeToggleResult(isLiked: true, likes: 1));
    } catch (e, stack) {
      _logError('toggleCommentLike', e, stack);
      return Result.failure(backendFailure(e, stack));
    }
  }

  // ──────────────────────────────────────────────────────────────
  // Image Upload
  // ──────────────────────────────────────────────────────────────

  /// Uploads an image to the Supabase Storage `posts` bucket and
  /// returns the public URL.
  @override
  Future<Result<String>> uploadImage(String userId, String filePath) async {
    const bucketName = 'posts';

    if (!SupabaseClientProvider.isInitialized) {
      Logger.error('Supabase not initialized.', tag: 'PostRepository');
      return Result.failure(const Failure('Supabase not initialized'));
    }

    try {
      final client = SupabaseClientProvider.client!;
      final authUser = client.auth.currentUser;

      Logger.info(
        '========== STORAGE DEBUG ==========\n'
        'Authenticated User: ${authUser?.id}\n'
        'Method userId: $userId\n'
        'Bucket: $bucketName\n'
        'File: $filePath',
        tag: 'PostRepository',
      );

      if (authUser == null) {
        return Result.failure(const Failure('No authenticated user found.'));
      }

      final file = File(filePath);

      if (!await file.exists()) {
        return Result.failure(Failure('Image file not found: $filePath'));
      }

      final bytes = await file.readAsBytes();
      final ext = file.path.split('.').last.toLowerCase();
      final storagePath =
          '${authUser.id}/${DateTime.now().millisecondsSinceEpoch}.$ext';

      Logger.info('Uploading to: $storagePath', tag: 'PostRepository');

      await client.storage
          .from(bucketName)
          .uploadBinary(
            storagePath,
            bytes,
            fileOptions: FileOptions(
              upsert: false,
              contentType: ext == 'png'
                  ? 'image/png'
                  : ext == 'webp'
                  ? 'image/webp'
                  : 'image/jpeg',
            ),
          );

      Logger.info('Upload successful.', tag: 'PostRepository');

      final publicUrl = client.storage
          .from(bucketName)
          .getPublicUrl(storagePath);

      Logger.info('Public URL: $publicUrl', tag: 'PostRepository');

      return Result.success(publicUrl);
    } on StorageException catch (e, stack) {
      _logError('uploadImage (StorageException)', e, stack);
      return Result.failure(Failure(e.message, error: e, stackTrace: stack));
    } catch (e, stack) {
      _logError('uploadImage (Unknown)', e, stack);
      return Result.failure(Failure(e.toString(), error: e, stackTrace: stack));
    }
  }

  // ──────────────────────────────────────────────────────────────
  // Mapping helpers
  // ──────────────────────────────────────────────────────────────

  /// Maps a Supabase row (with joined profile) to a [Post].
  ///
  /// [fallback] provides default values for fields that may be missing
  /// from the row (e.g. when the profile join returns null).
  Post _mapPostFromRow(Map<String, dynamic> row, Post fallback) {
    final profile = row['profiles'] as Map<String, dynamic>?;

    return Post(
      id: row['id'] as String,
      userId: row['user_id'] as String,
      username: profile?['username'] as String? ?? fallback.username,
      displayName: profile?['display_name'] as String?,
      avatarUrl: profile?['avatar'] as String?,
      content: row['content'] as String? ?? fallback.content,
      mediaUrls: row['media_urls'] != null
          ? List<String>.from(row['media_urls'] as List)
          : fallback.mediaUrls,
      likes: row['likes_count'] as int? ?? fallback.likes,
      comments: row['comments_count'] as int? ?? fallback.comments,
      shares: row['shares_count'] as int? ?? fallback.shares,
      createdAt:
          DateTime.tryParse(row['created_at'] as String? ?? '') ??
          fallback.createdAt,
      updatedAt: row['updated_at'] != null
          ? DateTime.tryParse(row['updated_at'] as String? ?? '')
          : null,
    );
  }

  /// Maps a Supabase row (with joined profile) to a [Comment].
  ///
  /// [fallback] provides default values for fields that may be missing
  /// from the row. When [fallback] is `null` (e.g. when loading a list
  /// of comments), sensible defaults are used.
  Comment _mapCommentFromRow(Map<String, dynamic> row, Comment? fallback) {
    final profile = row['profiles'] as Map<String, dynamic>?;

    return Comment(
      id: row['id'] as String,
      postId: row['post_id'] as String,
      userId: row['user_id'] as String,
      parentId: row['parent_id'] as String?,
      content: row['content'] as String? ?? fallback?.content ?? '',
      username: profile?['username'] as String? ?? fallback?.username ?? 'user',
      displayName: profile?['display_name'] as String?,
      avatarUrl: profile?['avatar'] as String?,
      likesCount: row['likes_count'] as int? ?? 0,
      isEdited: row['is_edited'] as bool? ?? false,
      isDeleted: row['is_deleted'] as bool? ?? false,
      createdAt:
          DateTime.tryParse(row['created_at'] as String? ?? '') ??
          fallback?.createdAt ??
          DateTime.now(),
      updatedAt: row['updated_at'] != null
          ? DateTime.tryParse(row['updated_at'] as String? ?? '')
          : null,
    );
  }

  // ──────────────────────────────────────────────────────────────
  // Debug logging helper (temporary)
  // ──────────────────────────────────────────────────────────────

  /// Logs detailed error information for debugging.
  ///
  /// Logs:
  /// - the exception
  /// - runtime type
  /// - full stack trace
  /// - if [PostgrestException]: code, message, details, hint
  void _logError(String operation, Object e, StackTrace stack) {
    logBackendError(operation, e, stack, tag: 'PostRepository');
  }
}
